"""Computes the average translation and rotation within a sequence (across subsequences of diff lengths)."""
def getStats(err: Any) -> object {
    t_err = 0;
    r_err = 0;
    for e in err {
        t_err += e[2];
        r_err += e[1];
    }
    t_err /= float(len(err));
    r_err /= float(len(err));
    return (t_err, r_err);
}

"""
    converts every special character into a separate token
    """
def clean_word(word: Any) -> object {
    cleaned_words = [];
    temp = "";
    for char in word {
        if (
            ((ord(char) >= 33) and (ord(char) <= 47))
            or ((ord(char) >= 58) and (ord(char) <= 64))
        ) {
            if (temp != "") {
                cleaned_words.append(temp);
                temp = "";
            }
            cleaned_words.append(char);
        } else {
            temp += str(char);
        }
    }
    if (temp != "") {
        cleaned_words.append(temp);
    }
    return cleaned_words;
}

